// Transaction-codec fixtures. Every hex was DECODED BY THE NODE
// (neuraid regtest, DePIN branch, v1.0.6.0-52297c1) and `txid`, `hash`,
// `size` and `vsize` are the values decoderawtransaction/getrawtransaction
// returned — never values computed by the codec under test, so txid/wtxid and
// the vout → vrefin → witness → locktime layout are validated against the
// node, not circularly.
//
// `walletV2` was fully generated by the node wallet (sendtoaddress +
// getrawtransaction). The other variants alter that base transaction
// (witness stacks, version 3, vrefin) and were then fed to the node's
// decoderawtransaction, which accepted them and produced the recorded values.

export interface TxCodecFixture {
  name: string;
  hex: string;
  txid: string;
  /** wtxid as the node reports it (`hash` field); equals txid without witness. */
  hash: string;
  version: number;
  vinCount: number;
  voutCount: number;
  size: number;
  vsize: number;
}

